SELECT

FROM spd_org_node n
LEFT JOIN spd_org_node pn ON n.parent_node_id = pn.node_id AND pn.del_flag = 0

    n.del_flag = 0

        AND n.node_name LIKE CONCAT('%', #{queryForm.nodeName}, '%')


        AND n.node_type = #{queryForm.nodeType}


        AND n.parent_node_id = #{queryForm.parentNodeId}


        AND n.tenant_id = #{queryForm.tenantId}


ORDER BY n.create_time DESC

SELECT

FROM spd_org_node n
LEFT JOIN spd_org_node pn ON n.parent_node_id = pn.node_id AND pn.del_flag = 0
WHERE n.id = #{nodeId}
AND n.del_flag = #{delFlag}

SELECT *
FROM spd_org_node
WHERE node_name = #{nodeName}
AND node_type = #{nodeType}
AND del_flag = #{delFlag}

    AND id != #{excludeNodeId}

LIMIT 1
